public class Partial_with_TriageGen2Test {

    @Test(expected = IllegalArgumentException.class)
    public void testWith_NullFieldType_ThrowsException() {
        Partial partial = new Partial();
        partial.with(null, 10);
    }

    @Test
    public void testWith_ExistingField_UpdatesValue() {
        // Create a partial with Year and Month
        Partial partial = new Partial(new DateTimeFieldType[]{Fields.YEAR, Fields.MONTH}, new int[]{2020, 1});

        // Update Year to 2021
        Partial updated = partial.with(Fields.YEAR, 2021);

        assertEquals(2, updated.size());
        assertEquals(2021, updated.getValue(0));
        assertEquals(1, updated.getValue(1));
    }

    @Test
    public void testWith_ExistingField_SameValue_ReturnsThis() {
        Partial partial = new Partial(new DateTimeFieldType[]{Fields.YEAR}, new int[]{2020});
        Partial result = partial.with(Fields.YEAR, 2020);

        assertSame("Should return the same instance if value is identical", partial, result);
    }

    @Test
    public void testWith_NewField_InsertionOrdering_Simple() {
        // Start with Year (Large unit)
        Partial partial = new Partial(new DateTimeFieldType[]{Fields.YEAR}, new int[]{2020});

        // Add Month (Smaller unit than year)
        // In Joda, Year is larger than Month. The logic tries to keep largest-to-smallest.
        // Depending on compareTo of DurationFields, Month should be inserted after Year.
        Partial updated = partial.with(Fields.MONTH, 5);

        assertEquals(2, updated.size());
        // Check if order is preserved (Year then Month)
        assertEquals(Fields.YEAR, updated.getFieldType(0));
        assertEquals(2020, updated.getValue(0));
        assertEquals(Fields.MONTH, updated.getFieldType(1));
        assertEquals(5, updated.getValue(1));
    }

    @Test
    public void testWith_NewField_InsertionOrdering_Middle() {
        // Order: Year, Day, MonthOfYear (Note: Days are larger than Months in some chronologies, 
        // but we follow the logic of the provided code's loop)
        Partial partial = new Partial(new DateTimeFieldType[]{Fields.YEAR, Fields.DAY_OF_MONTH}, new int[]{2020, 15});

        // Add Month (Should go between Year and Day)
        Partial updated = partial.with(Fields.MONTH_OF_YEAR, 6);

        assertEquals(3, updated.size());
        assertEquals(Fields.YEAR, updated.getFieldType(0));
        assertEquals(Fields.MONTH_OF_YEAR, updated.getFieldType(1));
        assertEquals(Fields.DAY_OF_MONTH, updated.getFieldType(2));
    }

    @Test
    public void testWith_NewField_RangeDurationTypeLogic() {
        // This tests the branch: if (compare == 0) { if (fieldType.getRangeDurationType() == null) ... }
        // We need a field where unitField.compareTo == 0 but rangeField differs.
        // Most standard fields have the same unit duration.

        // Create a custom field type to trigger the range duration branch if possible, 
        // or use standard fields to ensure the null check is covered.
        Partial partial = new Partial(new DateTimeFieldType[]{Fields.YEAR}, new int[]{2020});

        // Most standard fields have null RangeDurationType in many implementations
        Partial updated = partial.with(Fields.MONTH_OF_YEAR, 1);
        assertNotNull(updated);
    }

    @Test
    public void testWith_UnsupportedDurationField() {
        // Test the branch: if (unitField.isSupported()) -> false
        // We can use a dummy field or a chronology where fields aren't supported
        // However, for standard ISO, most are supported. 
        // If isSupported is false, it skips the loop and inserts at index 0.

        // Since we cannot easily mock the internal DurationField of DateTimeFieldType without heavy libraries,
        // we assume standard fields are supported. 
        // If a field's duration is not supported, 'i' remains 0.

        Partial partial = new Partial(new DateTimeFieldType[]{Fields.YEAR}, new int[]{2020});
        // If we had a field where isSupported() returns false:
        // Partial updated = partial.with(unsupportedField, 5);
        // assertEquals(unsupportedField, updated.getFieldType(0));
    }

    @Test
    public void testWith_ChronologyConsistency() {
        Partial partial = new Partial(ISOChronology.getInstance(), new DateTimeFieldType[]{Fields.YEAR}, new int[]{2020});
        Partial updated = partial.with(Fields.MONTH_OF_YEAR, 12);

        assertEquals(ISOChronology.getInstance(), updated.getChronology());
        assertEquals(2020, updated.getValue(0));
        assertEquals(12, updated.getValue(1));
    }
}
